    function __ESBMC_assume(bool) internal pure {}
    function run(address logAddr) public payable {
        uint256 preMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        uint256 preBal = address(c).balance;

        bool reverted;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

